#!/usr/bin/env node

/**
 * Block Generated Files Hook (PreToolUse / Edit|Write)
 *
 * Denies edits to files that are regenerated from source.
 * Tells Claude how to regenerate them instead.
 */

import { readFileSync } from 'fs'

const input = JSON.parse(readFileSync(0, 'utf-8'))
const filePath = input?.tool_input?.file_path

if (!filePath) {
  process.exit(0)
}

const projectDir = process.env.CLAUDE_PROJECT_DIR || ''
const rel = filePath.startsWith(projectDir + '/') ? filePath.slice(projectDir.length + 1) : filePath

const rules = [
  {
    test: (p) => p === 'src/payload-types.ts',
    reason: '`src/payload-types.ts` is auto-generated by Payload. Run `pnpm generate:types` to regenerate it from collection schemas. To change the types, edit the corresponding collection / field / global config.',
  },
  {
    test: (p) => p === 'src/app/(payload)/admin/importMap.js',
    reason: '`importMap.js` is auto-generated. Run `pnpm generate:importmap` to regenerate. To change it, edit the admin component imports in collections / globals.',
  },
  {
    test: (p) => /^src\/migrations\/.+\.json$/.test(p),
    reason: 'Migration JSON snapshots are auto-generated by `pnpm db:migrations:create`. Do not edit them by hand — ask the user to create a new migration instead.',
  },
  {
    test: (p) => /^src\/migrations\/.+\.ts$/.test(p),
    reason: 'Migration TS files are generated by `pnpm db:migrations:create` and should not be augmented (see .claude/rules/migrations.md). If a backfill or schema tweak is needed, surface the trade-off to the user and let them create a new migration.',
  },
]

const matched = rules.find((r) => r.test(rel))

if (matched) {
  const out = {
    hookSpecificOutput: {
      hookEventName: 'PreToolUse',
      permissionDecision: 'deny',
      permissionDecisionReason: matched.reason,
    },
  }
  console.log(JSON.stringify(out))
  process.exit(0)
}

process.exit(0)
